UPDATE session_category_stock
SET sold_count = sold_count + #{size}
WHERE session_id = #{sessionId} AND category_id = #{categoryId}
AND stock - sold_count >= #{size}

UPDATE session_category_stock
SET sold_count = sold_count - #{cnt}
WHERE session_id = #{sessionId} AND category_id = #{categoryId}
AND sold_count >= #{cnt}
